-- ============================================================================ -- V4__bot_binding_model.sql - Bot 绑定新增 AI 模型字段 -- -- 对应实体：com.chua.starter.ai.support.entity.SysAiBotBinding.model -- 说明：为已存在的 sys_ai_bot_binding 表补充 AI 模型列（用于微信聊天 AI 回复）。 -- ============================================================================  ALTER TABLE `sys_ai_bot_binding`     ADD COLUMN `sys_ai_bot_binding_model` VARCHAR(128) NULL COMMENT '绑定的 AI 模型（用于微信聊天时 AI 回复）' AFTER `sys_ai_bot_binding_bind_source`;